js = replace_once(js,
"""    const render = () => `<article class=\"one-sheet fundraiser-sheet\">${fundraiserSummary(analysis)}${durationNoticeSection([analysis])}${fundraiserVisualOverview(analysis, history)}${fundraiserHistoricalContext(analysis, history)}${fundraiserAirSchedule(analysis)}${fundraiserDailyTable(analysis)}${programResultsTable(analysis)}${singleTopicSummary(analysis)}<footer class=\"sheet-footer\">Program, daily, and topic $/hour use only observations with known results and valid duration; the displayed rate base identifies the denominator when it differs from scheduled pledge hours. Historical context uses fundraiser-balanced comparisons and excludes the selected fundraiser from its baseline when prior history is available. Non-Specific Pledges are not treated as incomplete program/topic data. Start-time performance is reserved for historical analytics where sufficient sample size can be required. Regional weather averages available Ironwood, Houghton, Marquette, Escanaba, and Sault Ste. Marie observations during each pledge window.</footer></article>`;\n""",
"""    const render = () => `<article class=\"one-sheet fundraiser-sheet\">${fundraiserSummary(analysis)}${durationNoticeSection([analysis])}${fundraiserVisualOverview(analysis, history)}${fundraiserHistoricalContext(analysis, history)}${fiscalYearToDateSection(analysis, history)}${fundraiserAirSchedule(analysis)}${fundraiserDailyTable(analysis)}${programResultsTable(analysis)}${singleTopicSummary(analysis)}<footer class=\"sheet-footer\">Program, daily, and topic $/hour use only observations with known results and valid duration; the displayed rate base identifies the denominator when it differs from scheduled pledge hours. Historical context uses fundraiser-balanced comparisons and excludes the selected fundraiser from its baseline when prior history is available. Fiscal YTD uses the July 1–June 30 WNMU fiscal calendar and includes only completed factual results through the selected fundraiser. Non-Specific Pledges are not treated as incomplete program/topic data. Start-time performance is reserved for historical analytics where sufficient sample size can be required. Regional weather averages available Ironwood, Houghton, Marquette, Escanaba, and Sault Ste. Marie observations during each pledge window.</footer></article>`;\n""",
'insert fiscal YTD into fundraiser report')

# Break-type table should show retained live evidence even if only one fundraiser has it.
js = replace_once(js,
"""      historicalRankingTable(analyses, 'breakType', 'Live break vs pre-recorded break', 'Each fundraiser contributes one rate per break type. Uses saved schedule live-break flags only; unmatched imported rows are excluded.'),\n""",
"""      historicalRankingTable(analyses, 'breakType', 'Live break vs pre-recorded break', 'Each fundraiser contributes one rate per break type. Uses saved schedule live-break flags only; unmatched imported rows are excluded. Live evidence is shown when at least one rate-valid live airing survives in saved schedule history.', { minAirings: 1, minFundraisers: 1, minTitles: 1 }),\n""",
'break type table threshold')

REPORTS.write_text(js)

